+    const int LROWS = mrows < nb ? nb : mrows;
+    for (int idx = tid; idx < LROWS * nb; idx += nthreads) {
         int r = idx / nb, c = idx - r * nb;
-        s[r * LDS + c] = Wm[(size_t)r * nb + c];
+        s[r * LDS + c] = (r < mrows) ? Wm[(size_t)r * nb + c] : 0.f;
     }
     __syncthreads();
-    // factor only min(mrows, nb) columns matter for rank, but the loop runs all nb
-    // columns; for mrows<nb the tail columns see all-zero sub-vectors (beta=0, tau=0).
-    caqr_smem_house<NWARPS>(s, mrows, nb, LDS, red);
+    caqr_smem_house<NWARPS>(s, LROWS, nb, LDS, red);
     __syncthreads();
-    // write nb x nb R: upper (r<=c) from smem row r, strict-lower = 0. Rows >= mrows
-    // are zero (rank<nb leaf).
+    // write nb x nb R: upper (r<=c) from smem row r, strict-lower = 0.
