__global__ void build_H_inplace_kernel(float* __restrict__ M, const float* __restrict__ R,
                                       const float* __restrict__ D, float* __restrict__ Tau,
                                       int n) {
    int mat = blockIdx.z;
    float* Mm = M + (long)mat * n * n;
    const float* Rm = R + (long)mat * n * n;
    const float* Dm = D + (long)mat * n;
    float* Tm = Tau + (long)mat * n;
    int i = blockIdx.y * blockDim.y + threadIdx.y;
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n && j < n) {
        long idx = (long)i * n + j;
        if (i == j) Tm[i] = -Mm[idx] * Dm[i];     // tau from pivot before overwrite
        if (i <= j) Mm[idx] = Rm[idx] * Dm[i];     // overwrite diag+upper with R*D
        // i > j (strict-lower = V) left untouched
    }
}
// Build H in place into M (returned) and tau into a fresh (batch,n) tensor.
std::vector<torch::Tensor> build_H_inplace(torch::Tensor M, torch::Tensor R, torch::Tensor D) {
    int batch = M.size(0), n = M.size(1);
    auto Tau = torch::empty({batch, n}, M.options());
    dim3 blk(32, 8);
    dim3 grid((n + 31) / 32, (n + 7) / 8, batch);
    build_H_inplace_kernel<<<grid, blk>>>(M.data_ptr<float>(), R.data_ptr<float>(),
                                          D.data_ptr<float>(), Tau.data_ptr<float>(), n);
    return {M, Tau};
}

// FP64 Gram via cublasDsyrk (HALF the FLOPs of a full GEMM; only ONE triangle is
// computed). A is (batch,n,n) row-major FP64; G is (batch,n,n) row-major FP64. In
// cuBLAS column-major terms the stored row-major A is A_math^T, so syrk(trans=N)
// on it yields A_cm A_cm^T = A_math^T A_math = G.
//   fill_torch_lower==0: cuBLAS FILL_MODE_LOWER -> col-major-LOWER == ROW-MAJOR-
//                        UPPER filled (use with cholesky_ex(upper=True)).
//   fill_torch_lower==1: cuBLAS FILL_MODE_UPPER -> col-major-UPPER == ROW-MAJOR-
//                        LOWER filled (use with cholesky_ex(upper=False) --
//                        cuSOLVER's LOWER potrf is ~2x faster than the
//                        blocked UPPER potrf at n=4096, a single big getrf-style
//                        kernel vs a swarm of small panel kernels).
// We do NOT mirror to the other triangle: cuSOLVER's cholesky_ex reads only the
// requested triangle, saving the full n^2 symmetrize copy.
// Fused FP64-lower -> FP32-upper transpose-cast: R = L^T as row-major upper FP32,
// in ONE pass over the n x n matrix. Replaces L64.float().transpose(-1,-2).contiguous()
// (a cast + a transposed materialize-copy, ~244us at n=4096,B=2) with a single
// strided read of the FP64 lower L and a contiguous write of the FP32 upper R
// (~98us, the cost of one n^2 FP32 write). Reads L[j,i] (lower, i>=j... actually
// L64 is lower so L[c,r] for c>=r), writes R[r,c]=L[c,r] for r<=c (upper), 0 below.
//   R is row-major (B,n,n) FP32; L is row-major (B,n,n) FP64 (lower-triangular).
__global__ void chol_L_to_R_kernel(const double* __restrict__ Lg, float* __restrict__ Rg,
                                   int n) {
    int mat = blockIdx.z;
    const double* L = Lg + (long)mat * n * n;
    float* R = Rg + (long)mat * n * n;
    int r = blockIdx.y * blockDim.y + threadIdx.y;
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (r < n && c < n) {
        // R upper: R[r,c] = L^T[r,c] = L[c,r] for r<=c (L lower has L[c,r], c>=r); else 0.
        R[(long)r * n + c] = (r <= c) ? (float)L[(long)c * n + r] : 0.f;
    }
}
// Out-variant: write R into a caller-provided (persistent) FP32 buffer (every
// element is written each call -- upper = L^T, strict-lower = 0 -- so reusing the
// buffer is safe). Avoids the per-call 256MB FP32 alloc of chol_L_to_R.
void chol_L_to_R_out(torch::Tensor L, torch::Tensor R) {
    int batch = L.size(0), n = L.size(1);
    dim3 blk(32, 8);
    dim3 grid((n + 31) / 32, (n + 7) / 8, batch);
    chol_L_to_R_kernel<<<grid, blk>>>(L.data_ptr<double>(), R.data_ptr<float>(), n);
}

