__global__ void chol_upper_to_R_kernel(const double* __restrict__ G, float* __restrict__ R,
                                      int n) {
    int mat = blockIdx.z;
    int r = blockIdx.y * blockDim.y + threadIdx.y;
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (r < n && c < n) {
        long idx = (long)mat * n * n + (long)r * n + c;
        R[idx] = (r <= c) ? (float)G[idx] : 0.f;
    }
}

