torch::Tensor recon_lu_cpp(torch::Tensor M, torch::Tensor R, torch::Tensor D,
                           int bs, int ob) {
    int batch = M.size(0), n = M.size(1);
    if (g_trsm_handle == nullptr) {
        BKL(cublasCreate(&g_trsm_handle));
        BKL(cublasSetMathMode(g_trsm_handle, CUBLAS_TF32_TENSOR_OP_MATH));
    }
    cublasHandle_t h = g_trsm_handle;
    float* Mp = M.data_ptr<float>();
    long nn = (long)n * n;
    const float one = 1.f, negone = -1.f;
    int nt = kLuNt;
    for (int jo = 0; jo < n; jo += ob) {
        int joe = (jo + ob < n) ? (jo + ob) : n;
        for (int j = jo; j < joe; j += bs) {
            int je = (j + bs < joe) ? (j + bs) : joe;
            int w = je - j;
            // --- no-pivot diagonal LU of the w x w block at (j,j) (custom kernel).
            // Static-smem fused kernel: bs=_LU_BLOCK<=64 always, so w<=64 (the proven
            // path); the static __shared__ float[64*64] covers the full w<=64 range.
            diag_lu_static_fused_kernel<<<batch, nt>>>(Mp, D.data_ptr<float>(), n, batch, j, w);
            float* blk = Mp + (long)j * n + j;           // diagonal block, ld=n
            if (je < n) {
                int mrows = n - je;
                float* L21 = Mp + (long)je * n + j;       // (mrows x w), ld=n
                // row-major X@U=B (U=upper(blk)) -> col-major U^T(lower) X_cm = B_cm:
                // trsm(LEFT, LOWER, OP_N, NON_UNIT, m=w, n=mrows)
                cublasSetMathMode(h, CUBLAS_DEFAULT_MATH);
                for (int mb = 0; mb < batch; ++mb)
                    BKL(cublasStrsm(h, CUBLAS_SIDE_LEFT, CUBLAS_FILL_MODE_LOWER,
                        CUBLAS_OP_N, CUBLAS_DIAG_NON_UNIT, w, mrows, &one,
                        blk + (long)mb * nn, n, L21 + (long)mb * nn, n));
                cublasSetMathMode(h, CUBLAS_TF32_TENSOR_OP_MATH);
            }
            if (je < joe) {
                int ncols = joe - je;
                float* U12 = Mp + (long)j * n + je;       // (w x ncols), ld=n
                // row-major V@X=B (V=unit-lower(blk)) -> col-major X_cm V^T(upper-unit)=B_cm:
                // trsm(RIGHT, UPPER, OP_N, UNIT, m=ncols, n=w)
                cublasSetMathMode(h, CUBLAS_DEFAULT_MATH);
                for (int mb = 0; mb < batch; ++mb)
                    BKL(cublasStrsm(h, CUBLAS_SIDE_RIGHT, CUBLAS_FILL_MODE_UPPER,
                        CUBLAS_OP_N, CUBLAS_DIAG_UNIT, ncols, w, &one,
                        blk + (long)mb * nn, n, U12 + (long)mb * nn, n));
                cublasSetMathMode(h, CUBLAS_TF32_TENSOR_OP_MATH);
                // within-panel Schur: M[je:n, je:joe] -= M[je:n, j:je] @ M[j:je, je:joe]
                int Rrows = n - je;
                float* L21b = Mp + (long)je * n + j;      // (Rrows x w)
                float* tr   = Mp + (long)je * n + je;     // (Rrows x ncols)
                // row-major C(Rrows x ncols) -= A(Rrows x w) @ B(w x ncols) ->
                // cublas gemm(N,N, ncols, Rrows, w, B, A, C) alpha=-1 beta=1 (TF32)
                BKL(cublasSgemmStridedBatched(h, CUBLAS_OP_N, CUBLAS_OP_N,
                    ncols, Rrows, w, &negone,
                    U12, n, nn, L21b, n, nn, &one, tr, n, nn, batch));
            }
        }
        if (joe < n) {
            int rest = n - joe, obw = joe - jo;
            float* Lp   = Mp + (long)jo * n + jo;         // (obw x obw) unit-lower
            float* U12w = Mp + (long)jo * n + joe;        // (obw x rest)
            // wide U12w = Lp^{-1} @ M (trsm_left, unit) -> trsm(RIGHT,UPPER,OP_N,UNIT, rest, obw)
            cublasSetMathMode(h, CUBLAS_DEFAULT_MATH);
            for (int mb = 0; mb < batch; ++mb)
                BKL(cublasStrsm(h, CUBLAS_SIDE_RIGHT, CUBLAS_FILL_MODE_UPPER,
                    CUBLAS_OP_N, CUBLAS_DIAG_UNIT, rest, obw, &one,
                    Lp + (long)mb * nn, n, U12w + (long)mb * nn, n));
            cublasSetMathMode(h, CUBLAS_TF32_TENSOR_OP_MATH);
            // wide Schur: M[joe:n, joe:n] -= M[joe:n, jo:joe] @ M[jo:joe, joe:n]
            float* L = Mp + (long)joe * n + jo;           // (rest x obw)
            float* tr = Mp + (long)joe * n + joe;         // (rest x rest)
            BKL(cublasSgemmStridedBatched(h, CUBLAS_OP_N, CUBLAS_OP_N,
                rest, rest, obw, &negone,
                U12w, n, nn, L, n, nn, &one, tr, n, nn, batch));
        }
    }
    return M;   // caller does in-place build_H + tau
}

