5984	// ONE-barrier fused diag_lu: a sync-cut over the base no-pivot diagonal-block LU
5985	// for the EXTREME-latency-bound recon regime (n=4096 recon, batch=2 -> only 2 CTAs on 148 SMs; an
5986	// nsys profile shows diag_lu is 33% of the recon and ~37us/64-col block, i.e. pure
5987	// __syncthreads chain latency, NOT FLOP-bound). The base kernel pays TWO barriers per
5988	// column: (A) after tid-0 writes the pivot to the diagonal slot so all threads can
5989	// read 1/pivot, and (B) after the trailing Schur update. This kernel REMOVES barrier
5990	// (A): every thread reads the column's diagonal (finalized by the prior column's
5991	// trailing update, visible across the single per-column barrier) and computes d / piv
5992	// / inv = 1/piv LOCALLY -- no cross-thread handoff of the pivot, so no barrier before
5993	// the trailing update. The diagonal slot is NEVER written during the loop (avoiding a
5994	// read-after-write race on it); the pivot is stashed in a separate smem `pivs[]` and
5995	// applied at the end (the diagonal becomes piv, the strict-lower entries are divided
5996	// by their column pivot -- the SAME deferred scale as the base kernel). Net: 1 barrier
5997	// per column instead of 2 -> halves the dominant per-block barrier latency.
5998	// Numerically IDENTICAL to the base two-barrier LU (same d/piv/inv, same trailing math,
5999	// same deferred scale): the trailing update at column kk reads only row kk (U-row,
6000	// final after column kk-1) and the RAW sub-diagonal column kk (scaled at the end), and
6001	// the diagonal it reads is the prior column's finalized Schur entry -- so V (strict-
6002	// lower) and the recon's (H,tau) are bit-for-bit the same. Shares all validation.
6003	__global__ void diag_lu_static_fused_kernel(float* __restrict__ Mg,
6004	                                            float* __restrict__ Dg,
6005	                                            int n, int batch, int j0, int w) {
6006	    int mat = blockIdx.x;
6007	    if (mat >= batch) return;
6008	    float* M = Mg + (long)mat * n * n;
6009	    float* D = Dg + (long)mat * n;
6010	    int tid = threadIdx.x, nt = blockDim.x;
6011	    __shared__ float sblk[64 * 64];   // static (w<=64)
6012	    __shared__ float pivs[64];        // per-column pivot (deferred to write-back)
6013	    for (int idx = tid; idx < w * w; idx += nt) {
6014	        int r = idx / w, c = idx % w;
6015	        sblk[idx] = M[(long)(j0 + r) * n + (j0 + c)];
6016	    }
6017	    __syncthreads();
6018	    for (int kk = 0; kk < w; ++kk) {
6019	        // All threads independently derive the column's pivot from its diagonal entry
6020	        // (finalized by the prior column's trailing update; the diagonal slot is not
6021	        // written during the loop, so this read is race-free). No barrier needed here.
6022	        float diag = sblk[kk * w + kk];
6023	        float d = (diag > 0.f) ? -1.f : 1.f;     // d != 0 (0 -> +1)
6024	        float piv = diag - d;
6025	        float inv = 1.0f / piv;
6026	        if (tid == 0) { D[j0 + kk] = d; pivs[kk] = piv; }
6027	        int rows = w - (kk + 1), cols = w - (kk + 1);
6028	        // Trailing Schur update with on-the-fly multiplier; raw L column untouched.
6029	        // Reads row kk (sblk[kk*w+c], final) and sub-diagonal col kk (sblk[r*w+kk],
6030	        // raw) -- NEITHER is the diagonal slot, so no hazard with pivs[] storage.
6031	        for (int idx = tid; idx < rows * cols; idx += nt) {
6032	            int rr = idx / cols, cc = idx % cols;
6033	            int r = kk + 1 + rr, c = kk + 1 + cc;
6034	            sblk[r * w + c] -= (sblk[r * w + kk] * inv) * sblk[kk * w + c];
6035	        }
6036	        __syncthreads();   // ONE barrier: trailing done + next diagonal visible
6037	    }
6038	    // Write-back: diagonal := pivs[r]; strict-lower := raw / pivs[c] (deferred scale);
6039	    // upper (r<c) unchanged. Same final factored block as the base two-barrier LU.
6040	    for (int idx = tid; idx < w * w; idx += nt) {
6041	        int r = idx / w, c = idx % w;
6042	        float v = sblk[idx];
6043	        if (r == c) v = pivs[r];
6044	        else if (r > c) v *= (1.0f / pivs[c]);
6045	        M[(long)(j0 + r) * n + (j0 + c)] = v;
6046	    }
6047	}
