// ONE-barrier fused diag_lu: a sync-cut over the base no-pivot diagonal-block LU
// for the EXTREME-latency-bound recon regime (n=4096 recon, batch=2 -> only 2 CTAs on 148 SMs; an
// nsys profile shows diag_lu is 33% of the recon and ~37us/64-col block, i.e. pure
// __syncthreads chain latency, NOT FLOP-bound). The base kernel pays TWO barriers per
// column: (A) after tid-0 writes the pivot to the diagonal slot so all threads can
// read 1/pivot, and (B) after the trailing Schur update. This kernel REMOVES barrier
// (A): every thread reads the column's diagonal (finalized by the prior column's
// trailing update, visible across the single per-column barrier) and computes d / piv
// / inv = 1/piv LOCALLY -- no cross-thread handoff of the pivot, so no barrier before
// the trailing update. The diagonal slot is NEVER written during the loop (avoiding a
// read-after-write race on it); the pivot is stashed in a separate smem `pivs[]` and
// applied at the end (the diagonal becomes piv, the strict-lower entries are divided
// by their column pivot -- the SAME deferred scale as the base kernel). Net: 1 barrier
// per column instead of 2 -> halves the dominant per-block barrier latency.
// Numerically IDENTICAL to the base two-barrier LU (same d/piv/inv, same trailing math,
// same deferred scale): the trailing update at column kk reads only row kk (U-row,
// final after column kk-1) and the RAW sub-diagonal column kk (scaled at the end), and
// the diagonal it reads is the prior column's finalized Schur entry -- so V (strict-
// lower) and the recon's (H,tau) are bit-for-bit the same. Shares all validation.
__global__ void diag_lu_static_fused_kernel(float* __restrict__ Mg,
                                            float* __restrict__ Dg,
                                            int n, int batch, int j0, int w) {
    int mat = blockIdx.x;
    if (mat >= batch) return;
    float* M = Mg + (long)mat * n * n;
    float* D = Dg + (long)mat * n;
    int tid = threadIdx.x, nt = blockDim.x;
    __shared__ float sblk[64 * 64];   // static (w<=64)
    __shared__ float pivs[64];        // per-column pivot (deferred to write-back)
    for (int idx = tid; idx < w * w; idx += nt) {
        int r = idx / w, c = idx % w;
        sblk[idx] = M[(long)(j0 + r) * n + (j0 + c)];
    }
    __syncthreads();
    for (int kk = 0; kk < w; ++kk) {
        // All threads independently derive the column's pivot from its diagonal entry
        // (finalized by the prior column's trailing update; the diagonal slot is not
        // written during the loop, so this read is race-free). No barrier needed here.
        float diag = sblk[kk * w + kk];
        float d = (diag > 0.f) ? -1.f : 1.f;     // d != 0 (0 -> +1)
        float piv = diag - d;
        float inv = 1.0f / piv;
        if (tid == 0) { D[j0 + kk] = d; pivs[kk] = piv; }
        int rows = w - (kk + 1), cols = w - (kk + 1);
        // Trailing Schur update with on-the-fly multiplier; raw L column untouched.
        // Reads row kk (sblk[kk*w+c], final) and sub-diagonal col kk (sblk[r*w+kk],
        // raw) -- NEITHER is the diagonal slot, so no hazard with pivs[] storage.
        for (int idx = tid; idx < rows * cols; idx += nt) {
            int rr = idx / cols, cc = idx % cols;
            int r = kk + 1 + rr, c = kk + 1 + cc;
            sblk[r * w + c] -= (sblk[r * w + kk] * inv) * sblk[kk * w + c];
        }
        __syncthreads();   // ONE barrier: trailing done + next diagonal visible
    }
    // Write-back: diagonal := pivs[r]; strict-lower := raw / pivs[c] (deferred scale);
    // upper (r<c) unchanged. Same final factored block as the base two-barrier LU.
    for (int idx = tid; idx < w * w; idx += nt) {
        int r = idx / w, c = idx % w;
        float v = sblk[idx];
        if (r == c) v = pivs[r];
        else if (r > c) v *= (1.0f / pivs[c]);
        M[(long)(j0 + r) * n + (j0 + c)] = v;
    }
}

