// ---------------------------------------------------------------------------
// diag_lu: NO-PIVOT LU of the w x w diagonal block at (j0,j0) of M (B,N,N),
// IN PLACE, with the orhr_col SIGN trick. ONE block per matrix (grid=batch);
// the whole w-column sequential factorization runs on-chip in static smem so
// there is NO per-column kernel launch (the Python loop was the n512 wall).
//
// Per column kk: every thread derives the pivot from the diagonal entry
// (finalized by the prior column's Schur update; the diag slot is not written
// during the loop, so the read is race-free). D[kk] = (diag>0 ? -1 : +1),
// piv = diag - D, inv = 1/piv. The Schur update uses the on-the-fly multiplier
// (raw L column / piv) so the diagonal slot is never written mid-loop. Pivots
// are stashed in pivs[] and applied at write-back (diag := piv; strict-lower :=
// raw / piv). Numerically identical to a two-barrier base LU (1 barrier/col).
// w <= 64 (static smem covers it). Matches the d60 validated reconstruction.
extern "C" __global__ void diag_lu(
    float* __restrict__ Mg, float* __restrict__ Dg,
    int n, int batch, int j0, int w)
{
    int mat = blockIdx.x;
    if (mat >= batch) return;
    float* M = Mg + (long)mat * n * n;
    float* D = Dg + (long)mat * n;
    int tid = threadIdx.x, nt = blockDim.x;
    __shared__ float sblk[64 * 64];
    __shared__ float pivs[64];
    for (int idx = tid; idx < w * w; idx += nt) {
        int r = idx / w, c = idx % w;
        sblk[idx] = M[(long)(j0 + r) * n + (j0 + c)];
    }
    __syncthreads();
    for (int kk = 0; kk < w; ++kk) {
        float diag = sblk[kk * w + kk];
        float d = (diag > 0.f) ? -1.f : 1.f;     // d != 0 (0 -> +1)
        float piv = diag - d;
        float inv = 1.0f / piv;
        if (tid == 0) { D[j0 + kk] = d; pivs[kk] = piv; }
        int rows = w - (kk + 1), cols = w - (kk + 1);
        for (int idx = tid; idx < rows * cols; idx += nt) {
            int rr = idx / cols, cc = idx % cols;
            int r = kk + 1 + rr, c = kk + 1 + cc;
            sblk[r * w + c] -= (sblk[r * w + kk] * inv) * sblk[kk * w + c];
        }
        __syncthreads();   // ONE barrier: trailing done + next diagonal visible
    }
    for (int idx = tid; idx < w * w; idx += nt) {
        int r = idx / w, c = idx % w;
        float v = sblk[idx];
        if (r == c) v = pivs[r];
        else if (r > c) v *= (1.0f / pivs[c]);
        M[(long)(j0 + r) * n + (j0 + c)] = v;
    }
}
