// ===========================================================================
// qr_panel2_sc: SINGLE-CTA on-chip panel factorization with explicit WARP-SHUFFLE
// reductions, emitting the EXACT outputs of the Triton _panel_factor2_kernel
// (the n=512 two-level IB-wide sub-panel). One block per matrix (grid=(B,)).
//
// WHY: ncu showed the Triton _panel_factor2_kernel is MIO-bound -- ~42% of stall
// cycles are scoreboard waits on the smem-staged tl.sum(axis=0) cross-warp
// reductions (Triton lowers axis=0 reductions through smem + a CTA barrier each
// time). This kernel replaces that mechanism: the b-column sweep runs ENTIRELY in
// shared memory (no per-column HBM round-trip), and each reduction (tail2, w[c])
// is a within-warp __shfl_down_sync tree + ONE tiny nwarps-wide smem combine --
// minimal smem traffic, one __syncthreads per reduction (no atomicAdd/threadfence
// like the multi-CTA path needs).
//
// Output contract == _panel_factor2_kernel (LAPACK dlarfg / geqrf convention):
//   * reads the panel from Asrc at (j,j), pheight rows x b cols (clone-fusion:
//     block 0 reads A, later blocks read H);
//   * writes the factored panel (R on/above diag, reflectors below) to Aout at
//     (j,j) -- pheight x b, only the b valid cols;
//   * tau[j+c] for c in [0,b);
//   * V^T into the COMBINED buffer at (c+voff_c, r+voff_r): Vt[c,r] = 1 if r==c,
//     panel[r,c] if r>c, else 0 (r,c relative to the sub-panel top);
//   * T (b x b, lower part built) into the combined buffer diagonal block at
//     (a+voff_c, c+voff_c).
// Panel held column-major in smem: sP[c*pheight + r] = panel(row r, col c).
// ===========================================================================
extern "C" __global__ void qr_panel2_sc(
    const float* __restrict__ Asrc,   // (B,N,N) row-major, read panel at (j,j)
    float* __restrict__ Aout,         // (B,N,N) row-major, write panel at (j,j)
    float* __restrict__ tauout,       // (B,N)
    float* __restrict__ Vtbuf,        // (B, NB, N) combined V^T buffer
    float* __restrict__ Tbuf,         // (B, NB, NB) combined T buffer
    int B, int N, int j, int pheight, int b, int voff_r, int voff_c,
    int strideAb, int strideAn,       // A/H strides (elements): batch, row
    int strideVb, int strideVk, int strideVn,
    int strideTb, int strideTk, int strideTn,
    int BLK)                          // sub-panel width (== IB; b <= BLK)
{
    const int bid = blockIdx.x;
    if (bid >= B) return;
    const int tid = threadIdx.x;
    const int NT  = blockDim.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int nwarps = (NT + 31) >> 5;

    extern __shared__ float smem_p2[];
    float* sP    = smem_p2;                       // pheight * BLK (column-major)
    float* sredw = sP + (long)pheight * BLK;      // nwarps * BLK warp-reduction scratch
    float* sbc   = sredw + (long)nwarps * BLK;    // broadcast: [0]=tail2, [1]=alpha, [2..]=w[c]

    const float* Ab = Asrc + (long)bid * strideAb + (long)j * strideAn + j;
    float* Hb       = Aout + (long)bid * strideAb + (long)j * strideAn + j;
    float* taub     = tauout + (long)bid * N + j;

    // Load the panel (row-major HBM) into sP (column-major smem). cols >= b -> 0.
    for (long idx = tid; idx < (long)pheight * BLK; idx += NT) {
        int r = idx % pheight;
        int c = idx / pheight;
        sP[(long)c * pheight + r] = (c < b) ? Ab[(long)r * strideAn + c] : 0.0f;
    }
    __syncthreads();

    for (int k = 0; k < b; ++k) {
        float* colk = sP + (long)k * pheight;     // column k
        float alpha = colk[k];

        // ---- tail2 = sum_{r>k} colk[r]^2  (warp-shuffle + nwarps smem combine) ----
        float part = 0.0f;
        for (int r = k + 1 + tid; r < pheight; r += NT) {
            float x = colk[r];
            part += x * x;
        }
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            part += __shfl_down_sync(0xffffffffu, part, off);
        if (lane == 0) sredw[warp] = part;
        __syncthreads();
        if (tid == 0) {
            float s = 0.0f;
            for (int w2 = 0; w2 < nwarps; ++w2) s += sredw[w2];
            sbc[0] = s;
        }
        __syncthreads();
        float tail2 = sbc[0];

        float beta, tau_k, scale;
        int has_refl = (tail2 > 0.0f);
        if (!has_refl) { beta = alpha; tau_k = 0.0f; scale = 1.0f; }
        else {
            float normx = sqrtf(alpha * alpha + tail2);
            float sgn = (alpha >= 0.0f) ? 1.0f : -1.0f;
            beta = -sgn * normx;
            tau_k = (beta - alpha) / beta;
            scale = 1.0f / (alpha - beta);
        }

        // build v into colk: v[r>k] = colk[r]*scale, v[k]=1 (temp; diag finalized later)
        for (int r = k + 1 + tid; r < pheight; r += NT) colk[r] *= scale;
        if (tid == 0) colk[k] = 1.0f;
        __syncthreads();

        // ---- w[c] = sum_{r>=k} v[r]*panel[r,c] for all c (one warp per column) ----
        // (computed for every c; T uses c<k, the trailing update uses c>k.)
        for (int c = warp; c < b; c += nwarps) {
            const float* colc = sP + (long)c * pheight;
            float acc = 0.0f;
            for (int r = k + lane; r < pheight; r += 32)
                acc += colk[r] * colc[r];
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                acc += __shfl_down_sync(0xffffffffu, acc, off);
            if (lane == 0) sbc[2 + c] = acc;
        }
        __syncthreads();

        // T column k (lower) from w[c<k]: T[a<k,k] = -tau_k * sum_{c<k} T[a,c]*w[c];
        // T[k,k]=tau_k; T[a>k,k]=0. (Matches the Triton Tcol build, FP-exact.)
        {
            float* Tb = Tbuf + (long)bid * strideTb;
            for (int a = tid; a < BLK; a += NT) {
                float val;
                if (a < k) {
                    float s = 0.0f;
                    for (int c = 0; c < k; ++c)
                        s += Tb[(long)(a + voff_c) * strideTk + (c + voff_c) * strideTn] * sbc[2 + c];
                    val = -tau_k * s;
                } else if (a == k) {
                    val = tau_k;
                } else {
                    val = 0.0f;
                }
                Tb[(long)(a + voff_c) * strideTk + (k + voff_c) * strideTn] = val;
            }
        }

        // apply to trailing cols c>k: panel[r,c] -= tau_k*v[r]*w[c], rows r>=k.
        if (has_refl) {
            for (int c = k + 1; c < b; ++c) {
                float wc = tau_k * sbc[2 + c];
                const float* vcol = colk;
                float* colc = sP + (long)c * pheight;
                for (int r = k + tid; r < pheight; r += NT)
                    colc[r] -= vcol[r] * wc;
            }
        }
        __syncthreads();

        // finalize column k diagonal: beta (or alpha if no refl). v[r>k] already set.
        if (tid == 0) { colk[k] = has_refl ? beta : alpha; taub[k] = tau_k; }
        __syncthreads();
    }

    // write the factored panel back to H (column-major smem -> row-major HBM), b cols
    for (long idx = tid; idx < (long)pheight * b; idx += NT) {
        int r = idx % pheight;
        int c = idx / pheight;
        Hb[(long)r * strideAn + c] = sP[(long)c * pheight + r];
    }
    // tau for cols >= b (out of the valid range) stays as written (only c<b set).
    // V^T into the combined buffer at (c+voff_c, r+voff_r):
    {
        float* Vb = Vtbuf + (long)bid * strideVb;
        for (long idx = tid; idx < (long)pheight * BLK; idx += NT) {
            int r = idx % pheight;
            int c = idx / pheight;
            float val;
            if (r == c) val = 1.0f;
            else if (r > c && c < b) val = sP[(long)c * pheight + r];
            else val = 0.0f;
            Vb[(long)(c + voff_c) * strideVk + (long)(r + voff_r) * strideVn] = val;
        }
    }
}
