import torch, sys, time
sys.path.insert(0,'problems/linalg/qr_v2')
import submission as S
from reference import generate_input
torch.manual_seed(0)
def per_iter_sync(fn, A, it=20):  # mimic benchmark: sync per iteration (CPU dispatch NOT amortized)
    for _ in range(3): fn(A); torch.cuda.synchronize()
    ts=[]
    for _ in range(it):
        torch.cuda.synchronize(); t0=time.perf_counter()
        fn(A); torch.cuda.synchronize()
        ts.append((time.perf_counter()-t0)*1e3)
    ts.sort(); return ts[len(ts)//2]
def tight(fn, A, it=20):  # amortized (dispatch overlaps GPU)
    for _ in range(3): fn(A)
    torch.cuda.synchronize(); t0=time.perf_counter()
    for _ in range(it): fn(A)
    torch.cuda.synchronize(); return (time.perf_counter()-t0)/it*1e3
for n,b in [(2048,8),(4096,2)]:
    A=generate_input(b,n,1,12345,'dense').contiguous()
